const technical:Record<string,string>={
'postgres-row-level-security-review-offshore-developer':'Begin with a role graph rather than a policy screenshot. List login roles, inherited membership, SET ROLE paths, table owners, superusers, BYPASSRLS attributes, migration identities, background workers, reporting tools, and connection-pool behavior. For SELECT, INSERT, UPDATE, and DELETE, record both USING and WITH CHECK expressions and the session values they depend on. Build two synthetic tenants with distinguishable rows, then exercise direct SQL, prepared statements, ORM queries, bulk jobs, administrative paths, and transaction reuse. FORCE ROW LEVEL SECURITY deserves an explicit decision because owners normally bypass policies. Test missing identity, malformed identity, cross-tenant identifiers, joins, subqueries, and a pool connection reused after tenant context changes. Explain plans for permitted and denied fixtures so authorization does not hide a performance collapse. The database owner approves roles and production policy; the developer supplies migrations, fixtures, and evidence without copying customer rows.',
'webauthn-passkey-recovery-handoff':'Treat recovery as a security ceremony, not a forgotten link beside sign-in. Diagram registration and assertion challenges, relying-party identity, allowed origins, user verification, discoverable credentials, attestation posture, credential naming, and revocation. Then draw the paths for a new device, a lost device, a stolen authenticated session, a deleted platform credential, and a person who has lost every enrolled authenticator. Each fallback must state what proof it accepts and what authority support holds. Test replayed challenges, wrong origin, wrong RP ID, missing verification, cloned support evidence, repeated recovery, revoked credentials, and notification failure. Do not log challenges, authenticator data, session secrets, or identifying support material unnecessarily. A recovery that is easier to phish than the primary method can erase the security benefit. Product, security, privacy, and support owners approve the final journey; engineering demonstrates exact state transitions and audit evidence.',
'node-graceful-shutdown-review':'Capture one timestamped lifecycle from signal delivery to process exit. On SIGTERM, mark the instance unavailable through the actual readiness mechanism, stop accepting new connections, and track every request or job already admitted. HTTP keep-alive, upgraded connections, database transactions, queue consumers, telemetry exporters, and worker threads need separate closure rules. A fixed sleep is not drainage evidence. Inject slow requests, a hung dependency, a streaming response, an active transaction, an idle keep-alive socket, and a job between checkpoint and acknowledgement. Define which work may finish, which client receives a retryable refusal, which operation must reconcile later, and what happens at the platform deadline. Ensure signal handlers cannot leave the event loop alive forever and that a second signal has an intentional meaning. The service owner defines safety; the developer instruments and tests the bounded sequence.',
'kubernetes-readiness-gate-review':'Name the custom PodCondition exactly and identify the controller permitted to patch status. New conditions default to false for readiness calculation until written, so controller absence can halt a rollout even when containers are healthy. Rehearse Pod creation before external registration, successful registration, rejected registration, slow external propagation, controller restart, deleted external object, and Pod deletion during an update. Observe Pod conditions, EndpointSlice membership, Deployment availability, external target state, events, and client probes on one timeline. Readiness does not drain every protocol instantly and does not prove application correctness. Define a timeout and recovery owner without adding a second controller that races the first. Verify RBAC is scoped to the necessary status update and that cleanup cannot remove another Pod’s registration. Platform owners approve production controllers and emergency bypass; the engineer provides a repeatable fixture and rollback manifest.',
'postgres-concurrent-index-handoff':'Rehearse against representative synthetic volume and a realistic mix of readers and writers. Record server version, table and existing-index definitions, relation sizes, data distribution, transaction age, replication context, maintenance settings, and the exact CREATE INDEX CONCURRENTLY statement. Observe pg_stat_progress_create_index, pg_locks, pg_stat_activity, wait events, application latency, and catalog validity through every phase. Seed a duplicate or expression failure where relevant, cancel during a declared phase, and inspect what remains. A failed concurrent build may leave INVALID catalog state; dropping or retrying it is an owner decision, not automatic cleanup. After success, compare EXPLAIN plans for representative parameter values and confirm the index supports the intended predicate and ordering. Database owners set resource budgets and production timing; the developer supplies measurements, cancellation evidence, cleanup options, and a re-test trigger.',
'github-actions-oidc-cloud-boundary':'Start from claims captured safely for the exact workflow context, then author the cloud trust relationship from allowlisted values. Repository, organization, ref, tag, pull-request context, environment, workflow identity, issuer, and audience are different boundaries; a wildcard chosen for convenience can admit an unintended caller. Use a protected deployment environment when human approval or branch restrictions are required, and keep the cloud role permissions narrower than its trust eligibility. Exercise default branch, feature branch, fork pull request, unapproved environment, different repository, altered audience, reusable workflow, and expired token. Record cloud session names and audit correlation without persisting the JWT. Test metadata or provider failure as closed, and remove legacy static secrets only after every legitimate path works. Security owns federation policy and incident response; platform owners approve deployment authority; the developer maintains workflow code and denied-case tests.',
's3-multipart-upload-cleanup-review':'Inventory incomplete uploads through the supported listing API and group them by bucket, prefix, initiating application version, age, part count, stored bytes, and known workflow. An incomplete multipart upload is not an object, and ordinary object listing will not reveal its retained parts. Reproduce a normal upload, client interruption before any part, interruption after several parts, retry with the same business operation, successful completion, explicit abort, and lifecycle-driven abort. Confirm how the client stores upload IDs and whether a long offline interval is legitimate. Apply a lifecycle rule only after the business owner defines an abandonment horizon longer than valid workflows. Monitor bytes as well as upload counts because a few large uploads dominate cost. Abort only synthetic fixtures during rehearsal. Storage owners approve bucket policy and lifecycle changes; the developer documents client recovery and evidence.',
'graphql-query-cost-control-review':'Build cost from schema semantics rather than string length. Assign documented weights to expensive fields, bound list multipliers by enforced pagination, account for aliases and fragments, and decide how interface or union selections contribute. Compare estimated cost with resolver calls, database queries, downstream requests, rows scanned, response bytes, and elapsed time for a controlled corpus. Include shallow-wide, deep-narrow, repeated aliases, nested lists, introspection according to policy, persisted operations, privileged fields, and a query that approaches but does not cross the limit. A static score cannot replace runtime timeouts, pagination, batching, caching, and authorization. Return a stable safe error that does not reveal internal weights unnecessarily. API owners set budgets and exceptions; schema owners maintain weights; the developer implements deterministic analysis and shows where observation contradicts the model.',
'react-error-boundary-recovery-handoff':'Choose boundaries around user-meaningful recovery units such as a route panel, editor, or optional dashboard, not around every component or only the entire application. Rendering, lifecycle, and constructor errors have different coverage from event-handler failures, asynchronous callbacks, server rendering, and errors inside the boundary itself. Create fixtures for each relevant class and record which boundary catches it. The fallback needs a useful name, focus target, explanation, preserved navigation, safe retry or escape, and telemetry correlation. Test repeated retry, failure during reset, stale data after recovery, nested boundaries, lazy chunk failure, and state that must not be silently discarded. Deduplicate reports without hiding recurrence, and avoid sending sensitive props or form contents. Product owners decide preservation and recovery language; frontend developers implement boundaries and interaction tests; operations owns alert routing.',
'container-image-signature-verification-review':'Begin with the exact digest selected by the deployment manifest; a mutable tag is only a lookup aid. Record registry host, media type, platform manifest, signature bundle, certificate identity, OIDC issuer, transparency evidence when used, source revision, and builder workflow. Write policy from allowlisted identities and claims rather than accepting any cryptographically valid signature. Exercise the approved build, a feature branch, another repository, a copied signature, an unsigned digest, altered provenance, unavailable transparency service, expired or revoked trust material, and a multi-architecture image whose child manifest differs. Verification should happen at the actual admission boundary and fail according to an approved availability policy. Security owns trust roots and exceptions; platform owners own enforcement; developers produce verifiable artifacts without gaining authority to approve their own release.',
'dns-cutover-evidence-handoff':'Lowering TTL shortly before a cutover does not change cached answers already retained under the older value. Record the old TTL early, authoritative nameservers, record chain, DNSSEC state, health-check behavior, proxy or CDN mode, certificate names, HTTP host handling, mail or verification dependencies, and rollback target. Query authoritative service plus a bounded set of independent resolvers before, during, and after the window, preserving answer, TTL, response code, and timestamp. Test the new origin directly with the intended Host and TLS name before changing DNS. During cutover, compare traffic and application health at both destinations until the longest relevant cache window has passed. Do not promise global propagation from a few samples. Domain owners approve record changes; service owners approve application readiness; the engineer collects evidence and stops on certificate, resolution, or health failures.',
'api-rate-limit-contract-review':'Choose the counted subject before choosing an algorithm: account, API key, authenticated principal, device, source network, route, operation cost, or a deliberate combination. Document fixed window, sliding window, token bucket, or concurrency behavior with its clock source and distributed storage assumptions. Send controlled requests around boundary instants, from two gateway replicas, with retries, cancellations, concurrent bursts, store latency, store outage, key rotation, shared networks, and approved exemptions. Verify 429 responses, safe problem details, Retry-After interpretation, and any limit headers used by clients. A successful backend call must not be counted twice because middleware retried internally. Decide fail-open or fail-closed by operation impact, not globally. Product owners set fair use and customer communication; security defines abuse response; engineering proves consistent enforcement and recovery.',
};

const acceptance:Record<string,string>={
'postgres-row-level-security-review-offshore-developer':'Accept only when the role matrix proves permitted operations and rejects every cross-tenant control through direct, ORM, worker, and pooled paths. Owner or BYPASSRLS connections, stale session context, incomplete command coverage, or an unexplained plan regression block release. Retain migration and rollback SQL, policy definitions, fixture IDs, query plans, and named approvers.',
'webauthn-passkey-recovery-handoff':'The journey passes when valid credentials work, revoked credentials fail, challenges cannot replay, origin and RP checks reject neighbors, and total device loss follows the approved recovery proof with timely notification. Any support shortcut, reusable recovery artifact, silent enrollment, or missing revocation evidence keeps the feature in review.',
'node-graceful-shutdown-review':'Acceptance requires new work to stop, admitted work to reach a documented outcome, resources to close, telemetry to flush within its budget, and the process to exit before forced termination. A hanging socket, uncertain side effect, acknowledged-but-unfinished job, or success exit after failed drainage is a release stop.',
'kubernetes-readiness-gate-review':'Pass when external registration and Pod conditions transition together, EndpointSlices reflect the intended state, controller restart recovers, and deletion cleans only the correct resource. Indefinite false conditions, excess RBAC, racing writers, or a rollout with no bounded escape remain platform-owner blockers.',
'postgres-concurrent-index-handoff':'Ready means the valid index builds within the approved resource envelope, intended plans can use it, cancellation leaves a known recoverable state, and cleanup is rehearsed. Invalid catalog entries, unexplained blocking, replica risk, or plan regressions prevent scheduling the production change.',
'github-actions-oidc-cloud-boundary':'Approve only when intended workflow contexts exchange successfully and every neighboring repository, ref, fork, environment, and audience is denied. The cloud session must have bounded lifetime and permissions, correlate in audit logs, and fail closed. Static keys remain until migration validation, then their removal is separately evidenced.',
's3-multipart-upload-cleanup-review':'Accept the rule when normal and legitimately slow fixtures complete, abandoned fixtures are aborted after the declared horizon, active clients recover predictably, and bytes decline as expected. Unknown upload owners, unbounded offline workflows, unexpected prefixes, or abort failures require a narrower rule or manual review.',
'graphql-query-cost-control-review':'The control passes when deterministic estimates reject seeded expensive operations, allow representative safe work, and correlate sufficiently with observed fan-out to support the declared budget. Unbounded list multipliers, bypass through fragments or aliases, unexplained false rejects, and undocumented overrides block rollout.',
'react-error-boundary-recovery-handoff':'Acceptance covers each intended throw source, announces the fallback, places focus, preserves or explicitly discards state, and provides a working escape or bounded retry. Infinite reset loops, lost consequential input, duplicate telemetry storms, or whole-app failure from an optional panel require redesign.',
'container-image-signature-verification-review':'Pass only when the pinned digest from the approved workflow satisfies identity and provenance policy while unsigned, cross-repository, wrong-branch, altered, and mismatched-platform fixtures are denied. Broad signer patterns, mutable-tag decisions, unverifiable bundles, silent fail-open behavior, or unexplained policy exceptions block admission rollout.',
'dns-cutover-evidence-handoff':'The cutover is ready when the new endpoint serves the intended Host with valid TLS and health, authoritative answers are correct, rollback remains viable, and the observation plan spans known cache windows. DNSSEC errors, certificate mismatch, unhealthy old or new origins, and undocumented dependent records are stop conditions.',
'api-rate-limit-contract-review':'Accept when multiple replicas produce the declared budget, boundary and burst fixtures are deterministic, clients receive actionable retry semantics, exemptions are owned, and store failure follows approved behavior. Counter divergence, identity collisions, retry amplification, or silent failure mode changes block release.',
};

const diagnostics:Record<string,string>={
'postgres-row-level-security-review-offshore-developer':'For investigation, capture current_user, session_user, active role membership, transaction-local tenant settings, and the policy expressions returned by the catalog beside every fixture result. Reuse one pooled connection across tenant A, tenant B, and a missing-context request to expose state leakage. Exercise COPY and maintenance tooling only when those paths exist. Verify that referential errors and row counts do not disclose another tenant indirectly. A policy that denies rows may still permit a timing or uniqueness signal, so record observable errors with security review. Keep a break-glass role outside normal application configuration, require named approval, and alert on its use. Re-run the entire matrix after schema ownership, ORM middleware, pool initialization, or worker identity changes.',
'webauthn-passkey-recovery-handoff':'Maintain an account-state ledger for the test persona: verified contact methods, enrolled credential IDs, backup eligibility and state where exposed, active sessions, recovery holds, notifications, and support actions. Verify that adding a passkey from an existing session follows the organization’s reauthentication rule. Recovery should not automatically preserve sessions that the incident model says may be compromised. Test two tabs attempting recovery, delayed email delivery, an authenticator restored from platform backup, and a user who recognizes an unexpected enrollment notice. Give support staff bounded outcomes rather than raw credential data. The handoff should state which uncertainty requires specialist identity review and which customer-facing claims are intentionally avoided.',
'node-graceful-shutdown-review':'Correlate load-balancer removal, readiness change, socket acceptance, application request IDs, transaction completion, queue acknowledgement, and process exit in one trace. Run the fixture with HTTP/1.1 keep-alive and every other protocol actually served. Confirm the orchestrator sends the signal the code handles and that the termination grace exceeds the application deadline plus platform routing delay. A health endpoint that flips only after listener close may be too late. Conversely, declaring unready before installing bounded handlers can create needless outage. Preserve the forced-kill experiment and the exact unfinished operations it leaves, then assign reconciliation to the correct owner instead of hiding it behind a successful restart.',
'kubernetes-readiness-gate-review':'Inspect status conditions with observed generation, reason, message, and transition time rather than reducing evidence to one Ready boolean. Compare the custom controller’s work queue with API updates and external target registration. Introduce an update conflict and temporary API failure to verify retry behavior without duplicate external resources. During rollout, confirm maxUnavailable and maxSurge interact safely with the delayed readiness condition. Pod deletion needs a finalization strategy that cannot hang forever; document its timeout and orphan cleanup owner. A manual status patch is diagnostic evidence only, not a routine recovery plan. Keep controller logs, resource versions, endpoint snapshots, and synthetic client results together.',
'postgres-concurrent-index-handoff':'Use application-shaped statements with parameters and record generic versus custom plans when that distinction matters. An index that exists and is valid may still be unused because statistics, predicate implication, collation, operator class, ordering, or selectivity differs from the proposal. Confirm write amplification and replica apply behavior during a sustained sample, not only build completion. If the index is partial, seed rows just inside and outside its predicate. If it is unique, stage the duplicate case and document business cleanup ownership. Schedule ANALYZE only when justified and separately approved. The final recommendation names the queries helped, those unchanged, new maintenance cost, and the condition that would make removal appropriate.',
'github-actions-oidc-cloud-boundary':'Pin third-party actions by the repository’s approved immutable reference policy and review which step can request id-token: write. Job-level permission can expose token minting to more steps than intended. In reusable workflows, distinguish the caller identity from the workflow repository claims supported by the provider. Test an environment name containing unexpected punctuation and a branch whose name resembles an allowed prefix. Cloud audit events should identify the workflow run and commit without granting trust based on mutable display text. If an exchange succeeds unexpectedly, revoke or narrow cloud trust first; editing logs or deleting the workflow does not invalidate an already issued session. Record maximum session duration and downstream role chaining.',
's3-multipart-upload-cleanup-review':'Calculate retained bytes from listed parts rather than assuming object size, and sample storage metrics after their documented delay. Verify pagination of upload and part listings so the inventory does not quietly stop at the first page. A client may start a replacement upload while an older ID remains abandoned; distinguish business object keys from upload identities. Where versioning, replication, object lock, access points, or cross-account uploaders exist, document whether they affect the scoped bucket workflow instead of guessing. The lifecycle configuration needs infrastructure-as-code ownership, review, and a rollback that stops future aborts without pretending already aborted parts can be restored. Alert thresholds should combine age and bytes.',
'graphql-query-cost-control-review':'Store the normalized operation and selected operation name for synthetic cases, but never retain production variables unnecessarily. Expand fragments before scoring and prevent circular-fragment handling from consuming resources itself. Enforce actual page-size arguments server-side; a scoring assumption about a default is unsafe if resolvers accept an unbounded value. DataLoader can reduce calls without reducing rows or downstream payloads, so compare several resource signals. Cost exceptions need a caller, operation hash, ceiling, purpose, and expiry. Schema changes that add a list field or alter resolver behavior should trigger corpus replay. The handoff includes false-positive and false-negative examples so maintainers understand where the model remains conservative or incomplete.',
'react-error-boundary-recovery-handoff':'Capture the component stack, release revision, route, boundary identity, and sanitized correlation ID once per failure episode. Reset keys should represent a meaningful new attempt, not change continuously and cause remount loops. When an error follows a user mutation, recovery must reconcile server truth before restoring optimistic state. Test browser back and forward navigation, focus after fallback, screen-reader announcement, reduced motion, and a second error thrown by the retry path. Lazy-load failure may need a fresh asset request or release-aware guidance rather than repeating the same rejected promise. The acceptance record distinguishes data reload, component remount, route escape, and support escalation so “Try again” always has defined behavior.',
'container-image-signature-verification-review':'Retain policy-engine version, trust configuration hash, admission request, safe verification output, and the exact digest in one case record. For keyless signing, validate certificate identity and issuer plus the repository and workflow claims carried by provenance; transparency inclusion alone does not authorize deployment. For managed keys, document custody, rotation, compromise response, and who may sign. Test registry mirror behavior and manifest-list resolution so verification cannot approve a parent while running an unexamined child. An emergency exception needs scope, approver, expiry, compensating observation, and removal proof. Re-test after builder, issuer, registry, admission controller, base image, or policy changes.',
'dns-cutover-evidence-handoff':'Query A, AAAA, CNAME, HTTPS or SVCB, CAA, and other applicable records rather than assuming the visible A answer is the complete route. Follow delegation from the parent when nameserver or DNSSEC changes are involved. Check both IPv4 and IPv6 origins, because a forgotten AAAA record can split clients after an otherwise correct cutover. Certificate validation should cover the real chain, SNI, hostname, expiry, and renewal path. Preserve resolver samples with their network and time, but do not turn public resolvers into a claim about every user. The rollback threshold names an application symptom and duration, who can change the record, and how long mixed answers remain expected afterward.',
'api-rate-limit-contract-review':'Use a deterministic clock in unit tests and a controlled shared store in integration tests. Run requests just before and after a window boundary, then repeat under clock skew and delayed counter writes. If limits vary by route cost, prove one expensive request consumes the intended units and cannot be fragmented into cheaper aliases. Hash or otherwise protect identifiers in rate-limit storage according to privacy rules. Retry-After may be seconds or a date depending on contract; test the chosen representation through the real gateway. Exemptions for health checks, internal automation, or trusted partners need bounded credentials and expiry. Dashboards should separate legitimate demand, suspected abuse, store faults, and policy misconfiguration.',
};

const rowSecuritySections = [
  {heading:'Start with the roles that reach the table',body:[technical['postgres-row-level-security-review-offshore-developer'],`A useful review starts at the connection boundary. Record the role named in the application configuration, the role that PostgreSQL reports after login, every membership it inherits, and whether the application changes role inside a transaction. Do the same for migrations, scheduled jobs, reporting tools, support consoles, and data repair scripts. This often changes the diagnosis. A policy can work perfectly for the web role while a worker reads as the table owner and bypasses it. The evidence packet should make that difference obvious before anyone edits SQL.`]},
  {heading:'Test commands separately',body:[`SELECT, INSERT, UPDATE, and DELETE do not share one policy decision. Build a matrix that names the applicable USING and WITH CHECK expression for each command. Insert a row with the correct tenant, then attempt the same write with another tenant and with no tenant context. For updates, test both the rows a caller may find and the new row values it may create. For deletes, verify the caller cannot infer protected rows from counts or error details. Keep the results by command instead of summarizing the suite as "RLS passed."`,`Joins deserve their own fixtures. Start with two tenants whose identifiers and row values are easy to distinguish. Join the protected table to an unprotected lookup, use a subquery, follow a foreign key, and exercise any view or function the application actually calls. Capture both returned rows and observable errors. The goal is not to prove that PostgreSQL hides every conceivable signal. It is to show what the reviewed query paths expose and to identify questions that need security ownership.`]},
  {heading:'Reproduce connection reuse',body:[diagnostics['postgres-row-level-security-review-offshore-developer'],`Pool reuse is where a sound policy can meet a faulty application boundary. In one test, set tenant A, execute a query, return the connection, then borrow it for tenant B. Repeat with a failed transaction and a cancelled request. Record whether the tenant value is transaction local, when cleanup runs, and what the next borrower observes. A test that creates a fresh connection for every tenant misses this failure. The correction may belong in transaction setup or pool cleanup rather than in the policy expression.`]},
  {heading:'Treat bypass as an owned exception',body:[`Table owners, superusers, and roles with BYPASSRLS need a named purpose. Keep them out of normal application configuration. If an administrative job needs wider access, document the job, the approved role, the query boundary, the audit event, and the person allowed to run it. FORCE ROW LEVEL SECURITY may be appropriate for some owner paths, but it changes operational behavior and needs database-owner approval. Do not switch it on simply to make a test green. A break-glass role also needs monitoring and an expiry or review rule.`,`Migration tooling is a separate concern. Schema changes may run as an owner even when the application does not. Rehearse the migration, application rollout, and rollback with the intended identities. Verify new policies exist before code depends on them and old policies remain until old code stops using them. The handoff should state which revision establishes each side of that compatibility window.`]},
  {heading:'Read performance evidence beside authorization evidence',body:[`A denied query returning no rows can still have an unsuitable plan. Save EXPLAIN output for permitted and denied synthetic cases, using representative parameter shapes without production data. Compare the predicates introduced by policy, index support, estimated rows, and execution work. If the policy calls a function, record its volatility and cost assumptions. Performance evidence does not relax authorization, but it can show that an apparently safe rollout would overload the database and needs an index or a narrower query before release.`,`Keep timing conclusions bounded. A small fixture cannot predict production latency, and timing differences can sometimes reveal information. Report what the fixture showed, what it did not model, and which owner decides whether further side-channel review is required. Do not turn one fast plan into a guarantee.`]},
  {heading:'Define a release decision that can be audited',body:[acceptance['postgres-row-level-security-review-offshore-developer'],`Package the final role graph, policy SQL, migration sequence, test matrix, connection-reuse trace, representative plans, known bypasses, and rollback steps under immutable revisions. The database owner approves roles and production policy. The security owner decides whether indirect signals and administrative paths are acceptable. The application owner confirms tenant context is established and cleared on every request path. An offshore developer can prepare the migration and evidence, but those approvals stay with the named internal owners.`]},
  {heading:'Handoff for the next working window',body:[`The next engineer should receive exact commands, fixture identifiers, expected row sets, actual row sets, PostgreSQL and client versions, the starting and ending commit, and the open decision. State whether they may continue testing, revise code, request a policy decision, or stop. Include the first condition that invalidates the result: a role change, new query path, pool configuration change, ownership transfer, ORM middleware change, or new administrative tool. That makes the review repeatable without pretending it is permanent.`]},
];
const passkeySections=[
 {heading:'Recovery changes the passkey threat model',body:[technical['webauthn-passkey-recovery-handoff'],`Write the account states on paper before designing screens: no credential, one usable credential, several credentials, a revoked credential, a lost device, and an account with no remaining authenticator. For each state, identify who may add or remove a credential and what proof that action requires. A recovery email that skips those rules is another authenticator, even if the interface calls it support.`]},
 {heading:'Keep WebAuthn checks intact',body:[`Exercise registration and assertion with the exact relying-party ID and origins used by the product. Preserve challenge creation and consumption, user verification requirements, credential identifiers, and the result of signature verification. Then send a reused challenge, a response for another origin, a response for another relying party, and a revoked credential. The expected result belongs in the test record beside the observed result.`,`Do not use logs as a second credential store. The evidence needs safe identifiers and decision reasons, not challenges, session cookies, signatures, or support documents. If a failure cannot be diagnosed without sensitive material, security and privacy owners should define a narrower diagnostic field rather than letting developers improvise.`]},
 {heading:'Test device loss as a journey',body:[diagnostics['webauthn-passkey-recovery-handoff'],`A lost phone is not one case. The user may still have an authenticated laptop, a synced credential on another device, a recovery factor, or nothing. Run each path with a synthetic account. Check which sessions survive, when notifications arrive, whether a hold applies, and whether an attacker with an old session can add a fresh credential during recovery.`]},
 {heading:'Give support bounded authority',body:[`Support needs explicit outcomes: explain an existing path, start a reviewed recovery case, place a temporary hold, or escalate. It should not receive raw authenticator data or silently override verification because a caller sounds convincing. Record the evidence support may request, retention rules, approval owner, rate limits, and the event sent to the account owner. Test repeated attempts and two agents handling the same case.`]},
 {heading:'Reconcile sessions and credentials',body:[`Successful recovery should end in a known account state. List active credentials, remove those the user or security owner has revoked, and decide which sessions must end. Confirm that an old credential fails after revocation and that an unexpected enrollment triggers a useful notice. A green sign-in test is incomplete if compromised sessions or recovery artifacts remain usable.`]},
 {heading:'Make notifications useful under attack',body:[`Send notices when recovery starts, when a credential is added or removed, when support changes a hold, and when recovery completes. The message should name the action and provide a safe route to report an unrecognized change without embedding a reusable recovery secret. Test delayed delivery, duplicate delivery, and a mailbox that an attacker may already control. An email cannot be treated as independent warning evidence when email possession is also the recovery proof.`,`Rate limits should cover account, contact method, network source, device, and support workflow as appropriate to the reviewed threat model. Test repeated starts, alternating identifiers, simultaneous browser tabs, and a recovery attempt while another hold is active. Record which state wins and how a legitimate user regains access after the limit. A generic success screen can reduce account discovery, but the internal event still needs a precise decision reason.`]},
 {heading:'Review authenticator replacement on an active session',body:[`An authenticated session may be stolen even when the original passkey remains secure. Require the organization’s approved reauthentication before adding a credential, changing recovery contacts, or removing the last known authenticator. Test a recently authenticated session, an old session, a session created before recovery began, and a session that loses authorization during the ceremony.`,`After a replacement, show the user enough information to distinguish credentials, such as the approved device label and enrollment time, without exposing authenticator internals. Verify the user can revoke the unexpected entry and that security can trace the event through safe identifiers. Product copy should not promise that a displayed device name proves physical possession.`]},
 {heading:'Acceptance and handoff',body:[acceptance['webauthn-passkey-recovery-handoff'],`The handoff includes account-state fixtures, browser and authenticator conditions, RP and origin settings, allowed fallback factors, notification results, denial evidence, support permissions, and open decisions. Product owns the recovery experience. Security approves proof and session consequences. Support owns the operating procedure. The developer implements the reviewed transitions and must stop when a requested shortcut changes that authority.`]},
];
const shutdownSections=[
 {heading:'Build one shutdown timeline',body:[technical['node-graceful-shutdown-review'],`Use one clock for the signal, readiness transition, listener close, last accepted request, completed response, queue acknowledgement, resource close, telemetry flush, and process exit. Without that timeline, a clean exit code can hide abandoned work. Run the fixture under the same termination grace and routing behavior used by the target platform.`]},
 {heading:'Separate admission from completion',body:[`Stopping new work and finishing accepted work are different controls. Close the listener, mark the instance unavailable through the real readiness path, and watch existing keep-alive connections. Test a fresh request, an idle reused connection, a slow response, and a streaming response after the signal. Record what the client sees and whether another instance can safely handle a retry.`,`Readiness changes do not instantly erase every route to the process. Load balancers, service proxies, and established connections have their own timing. The service owner must define the acceptable refusal and drain window; the engineer measures it rather than inserting an unexplained sleep.`]},
 {heading:'Decide the fate of background work',body:[diagnostics['node-graceful-shutdown-review'],`Pause queue intake before claiming drainage. For a job already running, record its checkpoint, external side effects, acknowledgement state, and recovery owner. Test shutdown before the first side effect, between two effects, and after completion but before acknowledgement. A generic retry is unsafe when the external action is not idempotent.`]},
 {heading:'Bound resource cleanup',body:[`Database pools, telemetry exporters, worker threads, timers, and upgraded sockets can keep the event loop alive. Give each resource an owner and a deadline. Close them in an order that still allows admitted work to finish. Inject a hung close and show that the overall deadline still wins. A second termination signal should have documented behavior instead of installing another unbounded wait.`]},
 {heading:'Make forced termination visible',body:[`Run one disposable case beyond the platform grace period. Preserve the operations left uncertain and verify the next instance can reconcile them. Do not mark the run successful merely because the orchestrator starts a replacement. Alert on forced kills, excessive drain time, unfinished jobs, and transactions whose outcome is unknown. Those signals point to different recovery actions. Keep the termination reason and deadline in the same trace so an operator can distinguish an application timeout from an external eviction.`]},
 {heading:'Keep readiness and shutdown ordering testable',body:[`Install the signal handler before the process advertises readiness. During termination, record when readiness changes relative to listener closure and the last accepted request. If the health endpoint shares the closing listener, the platform may miss the state transition; if readiness flips too early without replacement capacity, the rollout may reduce service availability. Test the actual routing components rather than assuming one ordering works everywhere.`,`Start a second instance during the fixture and send requests continuously across the transition. Classify completed responses, explicit retryable refusals, resets, timeouts, and duplicated work. A graceful process exit is only one observation. The client outcome and downstream side effects determine whether the replacement was safe.`]},
 {heading:'Design reconciliation before relying on retries',body:[`For each operation that can outlive a request, record an idempotency key, transaction boundary, queue acknowledgement point, or other approved reconciliation evidence. Then kill the process at that boundary and run the recovery path. If the system cannot determine whether an external side effect occurred, the handoff must assign investigation instead of automatically repeating it.`,`Telemetry needs its own bounded shutdown budget. Flush a synthetic final event, make the collector slow, and prove that observation cannot hold the process beyond the platform deadline. Mark missing telemetry as an evidence gap; do not reinterpret silence as successful drainage.`]},
 {heading:'Release evidence',body:[acceptance['node-graceful-shutdown-review'],`Package the signal configuration, platform deadline, routing observations, request and job fixtures, resource-close results, exit codes, and reconciliation steps. The platform owner approves termination settings. The service owner approves client and job outcomes. The developer may change lifecycle code and tests inside that boundary, but does not decide that an uncertain production side effect is safe. Record the previous service revision and its shutdown behavior so reviewers can distinguish a correction from a changed workload or routing condition.`]},
];

const readinessGateSections=[
 {heading:'Decide what the extra condition protects',body:[technical['kubernetes-readiness-gate-review'],`A readiness gate is useful only when container health is insufficient to decide whether a Pod should receive traffic. Name the external dependency and the exact state that makes the Pod eligible. Examples might include registration with an external load balancer or completion of a separate provisioning step, but the review must use the system that actually exists. If a normal readiness probe can test the condition safely, adding a controller and custom status writer may create more failure modes than it removes.`]},
 {heading:'Trace the condition from Pod creation',body:[`Create a Pod with the gate configured and watch its conditions before the custom controller writes anything. Record the condition type, status, reason, message, transition time, and observed generation. Compare those values with container readiness, the Pod Ready condition, Deployment availability, and EndpointSlice membership. This timeline answers a practical question: did traffic remain withheld for the intended reason, or did another probe or rollout rule determine the outcome?`,`Repeat the trace when the external registration completes quickly, completes slowly, and fails. The controller must distinguish an unfinished operation from a confirmed rejection. An empty status, an old status copied from another generation, and an explicit false status have different diagnostic meaning. Preserve the resource versions used for each patch so an update conflict is visible rather than mistaken for a controller outage.`]},
 {heading:'Break the controller without losing the rollout',body:[diagnostics['kubernetes-readiness-gate-review'],`Stop the controller after Pod creation but before it writes the condition. Restart it and verify that queued work is reconstructed from cluster state instead of relying on memory from the former process. Then introduce a temporary API write failure and an external API timeout. Count retries and external objects. A retry that creates a second registration is not recovery, even if one of the registrations eventually becomes healthy.`]},
 {heading:'Test replacement capacity',body:[`Delayed readiness consumes rollout capacity. Run the fixture with the Deployment's actual maxSurge and maxUnavailable values and note when old replicas terminate. If all replacement Pods wait on the same external service, a controller slowdown can stall the rollout or reduce available capacity. The evidence should show replica counts and endpoint membership throughout the update. Do not infer customer availability from the final Deployment status alone.`,`Test the opposite failure as well: the controller reports true before the external target can serve a request. Send a synthetic request through the external path and compare its time with the condition transition. The controller should not predict completion. If the external system has eventual propagation, define the observation that closes that gap and who owns its timeout.`]},
 {heading:'Make deletion specific and bounded',body:[`Delete one Pod while its external registration exists. The cleanup path must identify that Pod's resource without selecting by a mutable display name or a broad label. Verify that another replica remains registered. If a finalizer is used, make its timeout and orphan procedure explicit because a permanently unavailable external API can otherwise leave Pods stuck in termination.`,`Now delete a Pod before registration finishes and during a controller restart. Record whether the pending operation is cancelled, completed and then removed, or left for an orphan reconciler. Each outcome can be reasonable if it is deliberate. The dangerous outcome is an external target that survives unnoticed and later points at a reused address.`]},
 {heading:'Keep emergency action under platform ownership',body:[`A manual status patch can prove that the gate is responsible for a stalled rollout, but it is not a standing recovery method. State who may patch status, how the external registration is checked first, and when a rollout must pause instead. An emergency bypass needs a narrow workload, a time limit, observation of the traffic path, and a follow-up action that restores controller ownership.`,`Review RBAC separately from functional behavior. The controller should patch only the status it owns on the intended Pods. It should not receive broad workload mutation merely because that makes development easier. Capture the service account, role rules, binding scope, and a denied operation outside that scope.`]},
 {heading:'Evidence for the release decision',body:[acceptance['kubernetes-readiness-gate-review'],`The review packet includes the condition name, controller revision, RBAC, external resource identifier, Pod and EndpointSlice timelines, synthetic request results, failure injections, deletion outcomes, alert rules, and rollback manifest. Platform owners decide whether the controller and bypass procedure are acceptable. Service owners confirm what traffic readiness means. The developer supplies the reconciler change and repeatable evidence without using a production status patch as proof.`]},
];

const concurrentIndexSections=[
 {heading:'Start with the query and table, not the index name',body:[technical['postgres-concurrent-index-handoff'],`Record the statements the proposed index should help, including their parameter shapes, predicates, ordering, and row limits. Save the current plans and observed work before creating anything. The proposal should explain why existing indexes do not serve those statements. This prevents a handoff from treating successful DDL as the outcome when the planner has no reason to use the new structure.`]},
 {heading:'Build a rehearsal that resembles maintenance',body:[`Use synthetic or approved non-production data with comparable volume and distribution. Record PostgreSQL version, table size, index size, write rate, long-running transactions, replica context, maintenance settings, and free storage. Start representative reads and writes before issuing the exact CREATE INDEX CONCURRENTLY statement. A quiet empty table proves syntax, not operational safety.`,`Keep the SQL immutable in the evidence. Changes to an expression, predicate, collation, operator class, sort direction, included column, or uniqueness requirement can alter both build behavior and planner eligibility. If the review produces a revised definition, treat it as a new fixture and preserve why it changed.`]},
 {heading:'Observe every phase and its blockers',body:[`Sample pg_stat_progress_create_index, pg_stat_activity, pg_locks, wait events, application latency, replica delay, and storage during the build. Correlate the samples by time. Concurrent creation avoids the ordinary write lock of a standard build, but it still waits for transactions and performs significant work. Report the waits actually observed instead of calling the operation nonblocking.`,`Introduce one deliberately old transaction in rehearsal. Show which phase waits, what the application experiences, and how the operator identifies the session. The runbook must not assume that terminating a session is authorized. It should state the evidence, owner, and decision needed before any cancellation on a shared system.`]},
 {heading:'Cancel and inspect what remains',body:[diagnostics['postgres-concurrent-index-handoff'],`Cancel during a declared phase and inspect the catalog afterward. Record validity, readiness, size, locks, and write overhead. If an INVALID index remains, demonstrate the reviewed DROP INDEX CONCURRENTLY cleanup on the synthetic fixture. Do not hide this case by deleting the test database immediately after cancellation. It is the evidence that tells an operator what a failed production attempt would leave behind.`]},
 {heading:'Exercise uniqueness and predicates honestly',body:[`For a unique index, seed a duplicate that represents the business conflict and capture the resulting state. Assign cleanup of the underlying data to the data owner; the developer should not silently choose a winning row. For a partial index, seed rows on both sides of its predicate and use queries that do and do not imply that predicate. The planner cannot use an index simply because a reviewer knows two business descriptions are related.`,`Expression indexes need the same precision. Record the function definition, collation, and application expression. A harmless-looking rewrite in query code can stop matching the indexed expression. Add that neighboring query to the regression corpus rather than promising that all similar searches benefit.`]},
 {heading:'Check plan adoption and ongoing cost',body:[`After a successful build, run EXPLAIN for the preserved statement corpus with representative parameter values. Note generic and custom plans when prepared statements make that distinction relevant. Compare rows, buffers, sort work, and elapsed time carefully; a short isolated run does not establish production latency. State which statements improved, which did not change, and which regressed.`,`Measure writes during a sustained sample and inspect replica behavior. Every additional index adds maintenance work even when reads improve. Include the index in bloat, vacuum, backup, and schema ownership procedures. Define a later review trigger based on query use and write cost rather than leaving the index indefinitely because its build once succeeded.`]},
 {heading:'Schedule only from complete evidence',body:[acceptance['postgres-concurrent-index-handoff'],`The database owner receives the exact DDL, baseline and post-build plans, progress timeline, workload measurements, cancellation result, invalid-index cleanup, uniqueness or predicate fixtures, replica observations, storage requirement, and rollback conditions. The owner chooses the production window and any session intervention. The developer may prepare and rehearse the change, but cannot translate a clean rehearsal into permission to run maintenance on production.`]},
];

const oidcBoundarySections=[
 {heading:'Write the caller identity before the trust policy',body:[technical['github-actions-oidc-cloud-boundary'],`List the organization, repository, workflow file, ref or environment, issuer, audience, and cloud role for each permitted job. Keep these as separate fields. A policy that says "this repository may deploy" is incomplete when feature branches, pull requests, reusable workflows, and protected environments produce different claims. Capture claims from a safe test exchange without storing the token itself.`]},
 {heading:'Constrain token permission to the job that needs it',body:[`Review workflow and job permissions together. Grant id-token: write only where the exchange occurs, and keep repository-content and package permissions at the minimum required for that job. A job-level grant exposes token minting to every step in the job, including third-party actions. Pin those actions under the repository's approved immutable-reference policy and examine what runs before the exchange.`,`Separate trust from authorization. The cloud trust policy decides which workload may assume the role. The role policy decides what an admitted session may do. A narrow subject attached to an administrator role is still excessive, while a read-only role with a wildcard subject may leak data to unintended callers. Review both documents in the same packet.`]},
 {heading:'Build denied neighbors around the allowed case',body:[`Exchange from the approved default-branch or protected-environment job, then repeat from a feature branch, a similarly named branch, a fork pull request, another repository, an unapproved environment, and an altered audience. Include a repository name that shares the allowed prefix. Each denial should be attributable to a specific claim condition rather than to a broken test credential or network path.`,`Reusable workflows need an additional check. Record the claims that describe the caller and the called workflow under the chosen provider. Do not assume the workflow repository becomes the only identity simply because its YAML contains the deployment steps. The trust rule should reflect the provider's documented claims and the organization’s intended authority.`]},
 {heading:'Treat environment protection as part of the boundary',body:[`If human approval or branch restrictions are required, use the real protected environment in the fixture. Test a rejected approval, an absent approval, and an environment name with punctuation that affects the subject format. The exchange must not occur before the environment rules pass. Preserve the workflow run, commit, environment, and approval record as linked evidence.`,`Mutable names deserve care. Display names and branch labels help an operator read logs, but trust should rely on the exact supported claims and patterns. A prefix wildcard can admit names that merely look related. Enumerate the allowed forms and place a denied example beside every pattern.`]},
 {heading:'Follow the cloud session after exchange',body:[diagnostics['github-actions-oidc-cloud-boundary'],`Record the session name, role, start and expiry, requested audience, workflow run, source revision, and cloud audit event. Verify maximum session duration and any downstream role chaining. Do not log the JWT. The goal is to trace an action back to an approved workload without turning the evidence system into a credential leak.`]},
 {heading:'Remove static credentials only after migration proof',body:[`Run every legitimate deployment path through federation before deleting the old secret. Then revoke the static credential, remove it from repository or environment configuration, and demonstrate that the workflow still succeeds. Search configuration references and rotation procedures as well as workflow YAML. A secret hidden from the current job can still remain usable elsewhere.`,`Test provider metadata failure, audience mismatch, expired tokens, and unavailable cloud identity service. The job should stop without falling back to a long-lived key. If an unexpected exchange succeeds, narrow or revoke cloud trust first. Deleting a workflow or editing a log does not invalidate a cloud session that has already been issued.`]},
 {heading:'Approval rests on both allowed and denied evidence',body:[acceptance['github-actions-oidc-cloud-boundary'],`The packet contains the workflow revision, pinned actions, effective permissions, issuer and audience, subject conditions, environment protections, cloud role policy, allowed exchange, denied neighbors, session duration, audit correlation, fail-closed tests, legacy-secret removal evidence, and revocation procedure. Security owns federation and incident response. Platform owners approve deployment authority. The developer maintains the workflow and fixtures but does not broaden trust to make a failing branch pass.`]},
];

const multipartCleanupSections=[
 {heading:'Inventory uploads that ordinary object listings omit',body:[technical['s3-multipart-upload-cleanup-review'],`List incomplete multipart uploads with the supported API and follow every page of results. For each upload, enumerate its parts so retained bytes come from evidence rather than the eventual object size. Record bucket, key, upload ID, initiation time, initiating workflow, application version, part count, byte total, and any marker the client uses to resume. An incomplete upload is not a normal object, so an inventory built from object listings will miss the storage under review.`]},
 {heading:'Separate abandonment from a slow valid workflow',body:[`Map how the application starts, stores, resumes, completes, and abandons an upload ID. A browser that remains offline for a day, a field device on an unreliable connection, and a server-side batch may have very different valid gaps. The business owner should define those intervals before anyone picks an age threshold. The cleanup rule must follow the longest supported workflow, not an attractive round number.`,`A new upload for the same object key does not prove the older upload is abandoned. Clients can lose local state and start again while parts from the earlier ID remain. Grouping by business key helps investigation, but abort decisions still apply to the upload identity. Preserve that distinction in dashboards and support procedures.`]},
 {heading:'Reproduce the full client lifecycle',body:[`Use synthetic keys to run a completion, an interruption before the first part, an interruption after several parts, a resumed transfer, a replacement upload, an explicit abort, and an upload that remains active beyond a short test threshold. Record client state and S3 state at each step. The fixture should show whether the client can recognize that a lifecycle rule removed its upload and start safely again.`,`Test pagination for upload listings and part listings with enough synthetic entries to cross a page boundary. A script that quietly inspects only the first page can report a clean bucket while most retained bytes remain unseen. Preserve request counts or continuation markers so pagination is part of the evidence.`]},
 {heading:'Model the rule before enabling it',body:[diagnostics['s3-multipart-upload-cleanup-review'],`Express the proposed lifecycle configuration in the repository's infrastructure code and identify the exact bucket and prefix scope. Compare the rule with existing lifecycle entries because a broad prefix can affect unrelated applications. Review versioning, replication, object lock, access points, and cross-account initiation only where they exist in the scoped workflow. Do not invent compatibility conclusions for features that were not tested.`]},
 {heading:'Measure bytes, age, and client outcome',body:[`Count incomplete uploads and retained part bytes by age band. A count alone can hide a few very large transfers, while a byte total can hide a persistent client bug creating thousands of small uploads. Observe the storage metric after its documented reporting delay and keep API inventory time separate from metric time. Differences are a reason to investigate, not immediate proof that cleanup failed.`,`After the lifecycle rule aborts synthetic fixtures, attempt resume with the original upload IDs and capture the client's response. Confirm a new upload can complete and that a normal object with the same key was not removed. An abort is irreversible for those parts, so rollback can stop future cleanup but cannot restore data already discarded.`]},
 {heading:'Keep manual aborts narrow',body:[`During rehearsal, abort only the named synthetic upload IDs. A manual cleanup script should print its candidates and require the reviewed scope before mutation. It must not derive targets from a broad key glob or unresolved environment variable. If production inventory has unknown owners, stop at a report and assign identification rather than assuming old means safe to delete.`,`Alerts should combine age and bytes and identify the client workflow when possible. Repeated abandoned IDs from one application version call for a client fix, not merely a shorter lifecycle. Record abort failures, authorization errors, and the time until inventory reflects cleanup so operations can distinguish a broken rule from delayed observation.`]},
 {heading:'Acceptance belongs to storage and product owners',body:[acceptance['s3-multipart-upload-cleanup-review'],`The handoff contains paginated inventories, byte calculations, client-state diagrams, completion and interruption fixtures, resume behavior, proposed infrastructure code, prefix analysis, metric timing, abort results, alerts, and rollback limits. Storage owners approve bucket policy and lifecycle configuration. Product owners define legitimate offline duration. The developer corrects client recovery and supplies evidence without aborting unidentified production uploads.`]},
];

const graphqlCostSections=[
 {heading:'Derive cost from schema work',body:[technical['graphql-query-cost-control-review'],`Start with the fields that perform database scans, downstream calls, search, file work, or list expansion. Assign a documented weight only after describing that work. A character count or depth limit cannot see a shallow query that opens several wide lists. Conversely, a deeply nested selection over one bounded object may be cheap. Keep the weight table beside the schema revision it describes.`]},
 {heading:'Make list multiplication explicit',body:[`Enforce pagination arguments in resolvers and in the scorer. Record the default, maximum, and behavior when the argument is missing or invalid. Multiply nested lists according to the bounded values the server will actually honor. If the scorer assumes ten items but a resolver accepts an unbounded value, the estimate is not conservative; it is disconnected from execution.`,`Interfaces and unions require a declared rule for possible selections. Fragments should be expanded before scoring, aliases should not make repeated expensive work free, and circular-fragment handling must terminate cheaply. Use normalized synthetic operations to prove those parser paths without retaining production variables.`]},
 {heading:'Build a corpus that challenges the model',body:[`Include a shallow-wide query, a deep-narrow query, repeated aliases, nested lists, fragments shared across branches, an operation with several named queries, a persisted operation, introspection according to policy, a privileged field, and operations just below and above the threshold. Save the selected operation name and expected score for each fixture. A test suite made only of obvious attack queries will miss false rejections in normal product work.`,`Run the corpus under two roles when authorization changes visible fields or list sizes. The score must not accidentally grant access, and authorization must not be counted as a resource control. Decide whether a privileged operation receives a separate reviewed budget or must fit the common limit.`]},
 {heading:'Compare estimates with several resource signals',body:[`For each fixture, collect resolver invocations, database calls, rows scanned, downstream requests, response bytes, elapsed time, and any timeout. DataLoader may reduce call count without reducing rows or payload, so one metric cannot validate the model. Plot or tabulate estimate beside observation and keep the outliers. Those outliers are where weights, resolver design, or the control boundary needs more work.`,`Repeat the corpus with a warm and cold cache if caching materially changes execution. The static score should describe permitted work, not depend on a lucky cache hit. Runtime deadlines, pagination, batching, cache policy, and downstream circuit breakers remain necessary even after the score correlates well.`]},
 {heading:'Design rejection as part of the API contract',body:[diagnostics['graphql-query-cost-control-review'],`Return a stable error that clients can distinguish from authentication, validation, and server failure. Avoid publishing enough internal weight detail to make the schema easier to probe unless the API intentionally exposes a cost contract. Test that rejection happens before expensive resolvers start and that telemetry records a safe operation identifier, caller class, estimate, limit, and outcome.`]},
 {heading:'Give exceptions an end date',body:[`An exception needs a caller, normalized operation hash, business purpose, approved ceiling, owner, and expiry. Do not exempt an entire client or disable analysis for persisted queries. Replay exceptions whenever the schema or resolver behavior changes. At expiry, the operation should return to the standard budget unless an owner reviews new evidence.`,`Track false positives, false negatives, rejected operations, runtime overruns below the threshold, and overrides still in use. An operation whose low score repeatedly produces high work is a model defect. A high-scoring operation that executes cheaply may point to a weight that is too coarse, but lowering it requires corpus evidence rather than pressure from one client.`]},
 {heading:'Retest when the schema changes',body:[`A new list field, altered pagination maximum, resolver rewrite, or downstream fan-out can invalidate yesterday’s weights without changing an existing operation text. Make corpus replay part of schema review and compare both scores and observed work. Store the schema and scorer revisions with the result so a later discrepancy can be reproduced.`]},
 {heading:'Release with a maintained scoring model',body:[acceptance['graphql-query-cost-control-review'],`The API owner receives the schema revision, weight table, pagination enforcement, parser rules, complete corpus, expected and actual scores, resource observations, rejection contract, runtime safeguards, exception register, telemetry, and re-test triggers. Schema owners maintain weights when fields change. The developer implements deterministic scoring and fixtures, but cannot grant an undocumented override or treat the static model as a substitute for operational limits.`]},
];

const reactRecoverySections=[
 {heading:'Draw boundaries around recoverable user work',body:[technical['react-error-boundary-recovery-handoff'],`Choose a boundary by asking what the user can still do after a subtree fails. An optional dashboard panel can fail without destroying navigation. An editor may need a route-level escape and an explanation of draft state. A boundary around every component creates fragmented fallbacks and noisy reports, while one boundary around the entire application makes a minor widget failure catastrophic. Record the reason for each boundary in terms of recovery, not component ownership.`]},
 {heading:'Test what a boundary can and cannot catch',body:[`Create fixtures for render, constructor, and lifecycle failures in the relevant subtree. Add separate cases for an event handler, an asynchronous callback, server rendering, lazy loading, and an error thrown by the fallback itself. Record which boundary catches each case and what handles the rest. This keeps the handoff from claiming that error boundaries are a universal JavaScript exception mechanism.`,`Use the real route and composition hierarchy. A story that mounts the component directly may bypass the parent boundary or provider behavior that exists in the application. Preserve the component stack, release revision, route, boundary identity, and a sanitized correlation ID for each failure episode.`]},
 {heading:'Make the fallback usable without a mouse',body:[`Give the fallback a specific description of the failed area, move focus to an appropriate target, announce the change to assistive technology, and retain navigation that still works. Test keyboard order, screen-reader announcement, browser back and forward, reduced-motion settings, and zoom. A visually polished card is not sufficient if focus remains trapped in the removed subtree.`,`Offer only actions with defined behavior. "Try again" might reload data, reset a component, remount a route, or request a fresh asset. Name which one it performs. Include an escape when repeating the same attempt cannot change the condition, and make support escalation useful without exposing stack traces or internal identifiers to the page.`]},
 {heading:'Treat state loss as a product decision',body:[`For each boundary, list local input, server-confirmed data, optimistic mutations, URL state, and cached data. Trigger a failure after the user edits a field, after a mutation is sent, and after the server accepts it but before the interface receives confirmation. Recovery should reconcile server truth before restoring optimistic state. Never imply that input was saved unless the evidence shows where it was persisted.`,`A checkout or editor may contain consequential work that cannot be reconstructed. In that case, preserve state outside the failing subtree where safe, or provide an explicit route that lets the user review server state. Product owners decide which loss is acceptable. The developer should not silently trade user work for a simpler remount.`]},
 {heading:'Reset only on a meaningful new attempt',body:[diagnostics['react-error-boundary-recovery-handoff'],`Choose reset keys that change when the failed input, route, data revision, or release changes. A value that changes on every render can create an infinite remount loop and a telemetry storm. Test repeated retry, failure during reset, a second error in the fallback path, and navigation away and back. Count reports per episode rather than per render.`]},
 {heading:'Handle lazy assets as a release problem',body:[`A lazy chunk can fail because of a transient request, an old document referencing a removed asset, or a broader network condition. Capture the requested asset, HTTP outcome, document revision, and deployed release. A retry that reuses the same rejected promise may never issue another request. Decide whether the application retries the asset, reloads under a controlled condition, or asks the user to leave the affected route.`,`Do not turn every chunk failure into an automatic page reload. A loop between an old document and unavailable assets can strand the user and erase state. Bound attempts, preserve a release-aware reason, and provide navigation or support guidance after the bound is reached.`]},
 {heading:'Keep telemetry diagnostic and private',body:[`Send one report for the failure episode with the error class, component stack, route, boundary, release, and sanitized correlation. Remove form values, tokens, URLs with sensitive query data, and user-entered text unless a reviewed telemetry contract permits them. Test reporter failure so the fallback remains available when observation is unavailable.`,`Link retry outcome to the original episode. A successful reset, route escape, repeated failure, and support action are different outcomes. This tells maintainers whether the fallback helps users rather than merely proving that it rendered.`]},
 {heading:'Acceptance proves recovery, not just containment',body:[acceptance['react-error-boundary-recovery-handoff'],`The frontend owner receives the boundary map, throw-source fixtures, state inventory, fallback accessibility results, reset behavior, lazy-asset evidence, telemetry fields, privacy review, browser navigation tests, and each recovery outcome. Product owns what may be discarded. Accessibility and privacy owners review their respective behavior. The developer implements the agreed boundaries without hiding unresolved data loss behind a generic retry button.`]},
];

const imageSignatureSections=[
 {heading:'Verify the digest that will run',body:[technical['container-image-signature-verification-review'],`Resolve the workload image to an immutable digest and keep that digest in the admission fixture, signature output, provenance record, and runtime observation. A mutable tag can point to different content between review and deployment. If the registry returns a multi-platform index, identify the child manifest selected for the target platform and prove the policy covers the artifact that the node actually pulls.`]},
 {heading:'Define the signer as a workload identity',body:[`For keyless signing, record the certificate issuer and the exact identity claims for the approved repository, workflow, ref, and environment. A valid certificate and transparency entry prove that a signing event occurred; they do not by themselves grant that workflow deployment authority. Build the authorization rule from allowlisted identity values and keep denied neighboring identities beside the allowed fixture.`,`For a managed signing key, document custody, access policy, rotation, backup, and compromise response. Do not mix keyless and managed-key assumptions in one policy. The verifier must know which trust root and identity form applies to the artifact under review.`]},
 {heading:'Bind provenance to the build under review',body:[`Inspect source revision, repository, builder identity, workflow, build parameters, and subject digest in the available provenance. Compare the subject with the image digest rather than relying on a tag or release name. Decide which fields are mandatory for this deployment class and how the policy treats a missing or malformed field. Preserve safe verification output and the policy revision used for the decision.`,`Test a signature from an approved signer over a different digest, provenance naming another repository, a workflow on an unapproved branch, and an unsigned image. These are distinct failures. A useful denial record states which constraint failed without leaking credentials or dumping an entire certificate bundle into application logs.`]},
 {heading:'Exercise the registry and platform edges',body:[`Pull through every registry mirror or proxy used by the target cluster. Confirm digest preservation and observe how the verifier retrieves signatures and provenance. Test a manifest list with different child images for the supported architectures. Approval of the parent reference must not become permission to run an unexamined platform image.`,`Introduce registry unavailability, transparency-service failure where applicable, an unknown issuer, an expired certificate, a missing signature, and corrupted verification material. The admission policy should follow its declared failure behavior. A silent allow during verifier failure changes the security boundary and requires explicit owner approval, not an operational convenience.`]},
 {heading:'Put verification at the admission decision',body:[diagnostics['container-image-signature-verification-review'],`Capture the admission request, resolved digest, policy-engine version, trust configuration hash, decision, latency, and safe reason. Then inspect the created workload and running Pod to ensure the admitted digest remains the one used. If another controller mutates images, define whether verification occurs before or after that mutation and reject any path that can swap content after approval.`]},
 {heading:'Constrain exceptions and revocation',body:[`An emergency exception needs the exact digest or narrowly scoped workload, approver, reason, start, expiry, compensating observation, and removal evidence. It should not disable verification across a namespace because one release is urgent. Test expiry and make sure a copied workload does not inherit authority accidentally.`,`Rehearse signer compromise. Narrow or remove trust, attempt admission of a newly signed synthetic image, and decide how existing workloads are assessed. Certificate expiry, workflow removal, and source deletion are not substitutes for a revocation plan. Record what requires redeployment and what requires incident-owner judgment.`]},
 {heading:'Keep policy changes reviewable',body:[`Store admission policy and trust configuration under immutable revision. Test a tightening change, a signer rotation, and an attempted broadening before applying them to the protected workload. Compare policy-engine output across versions because parser or bundle changes can alter a decision even when the visible rule text is unchanged. The rollout plan should preserve a known-good policy revision without allowing unsigned images during rollback.`]},
 {heading:'Approve the policy with denied evidence',body:[acceptance['container-image-signature-verification-review'],`The platform and security owners receive the digest chain, signer identity, provenance requirements, trust roots, policy revision, allowed case, denied fixtures, registry and platform tests, admission record, runtime digest check, failure behavior, exception procedure, and revocation rehearsal. The developer can update build and policy code and collect evidence. Broadening signer patterns or enabling fail-open behavior remains an owner decision.`]},
];

const dnsCutoverSections=[
 {heading:'Map every name and endpoint before changing records',body:[technical['dns-cutover-evidence-handoff'],`Record the public hostname, authoritative zone and record identifiers, current answers, target answers, TTL history, aliases, address families, certificate names, health paths, origin configuration, and dependent records. Query A, AAAA, CNAME, HTTPS or SVCB, and CAA where they apply. A plan based only on the visible A record can leave IPv6 users or alias targets on a different path.`]},
 {heading:'Prove the new origin without public DNS',body:[`Send the intended Host and TLS server name directly to the new endpoint using a safe test path. Check the certificate chain, hostname coverage, expiry, renewal arrangement, redirects, application response, asset loading, and health behavior. Test both IPv4 and IPv6 when both will be published. This separates origin defects from resolver caching before the cutover begins.`,`Repeat the same checks against the old origin. Rollback is credible only while the old path remains healthy and its certificate still covers the name. Record how long it will remain available and which configuration changes after cutover could make it unsafe to restore.`]},
 {heading:'Treat TTL as a cache horizon, not a switch',body:[`Record when the previous TTL became authoritative and allow its full window before relying on a lower value. At cutover, sample the authoritative servers and a bounded set of recursive resolvers with timestamps and network context. Mixed answers can be expected during cache expiry; the plan should distinguish that state from a wrong authoritative record.`,`Do not claim that several public resolvers represent every user. Use them as evidence of propagation paths, then pair answer distribution with application health and traffic at the origins. A resolver can retain data according to behavior outside the planned sample, and clients may add local caching.`]},
 {heading:'Follow delegation and DNSSEC when they are in scope',body:[`If nameservers, DS records, or signed-zone material change, trace delegation from the parent and validate the chain. Record serials, signer state, and responses from each authoritative server. A correct record on one server is insufficient when the delegation still reaches another server with old data.`,`A DNSSEC validation failure may look like a missing domain to validating resolvers while direct authoritative queries appear correct. Make validation a stop condition. Ownership of registrar and parent-zone changes stays with the domain owner; an infrastructure developer can prepare evidence but should not improvise around failed delegation.`]},
 {heading:'Observe the application through the cutover',body:[diagnostics['dns-cutover-evidence-handoff'],`Chart authoritative answers, sampled recursive answers, certificate checks, health responses, origin request counts, error rates, and traffic split on one timeline. Send a unique harmless synthetic request through old and new answers so evidence identifies the responding origin. Check redirects and asset hosts, not only the first HTML response.`]},
 {heading:'Write rollback as another DNS transition',body:[`Define the application symptom, duration, and owner that trigger rollback. Preserve the exact old value and the authority needed to restore it. After restoration, expect mixed answers for another cache window and keep both origins healthy accordingly. Rollback time is not the moment a record is edited; it includes the period in which resolvers and clients still use the failed target.`,`If data or sessions change during the cutover, verify that directing traffic back is safe. DNS can restore routing but cannot reverse a database migration, queued side effect, or incompatible cookie. Assign those dependencies to their owners and block the cutover when the rollback story requires untested application behavior.`]},
 {heading:'Check certificate renewal after routing changes',body:[`Confirm which endpoint answers the certificate authority’s validation method after cutover and after rollback. A certificate that is valid on release day can still fail at renewal if validation reaches an origin without the required challenge or if CAA no longer permits the issuer. Record the renewal owner and the next test date alongside the current certificate evidence.`]},
 {heading:'The release packet establishes authority and timing',body:[acceptance['dns-cutover-evidence-handoff'],`The infrastructure owner receives zone identifiers, old and new record sets, TTL history, direct-origin checks, TLS evidence, resolver samples, delegation and DNSSEC results where applicable, timeline, health and traffic observations, rollback threshold, old-origin retention, and named approvers. The developer may rehearse and monitor the change. Domain authority and the decision to cut over or restore remain with the designated owner.`]},
];

const rateLimitSections=[
 {heading:'Define what consumes a budget',body:[technical['api-rate-limit-contract-review'],`Name the counted identity and how it is derived for authenticated users, API clients, anonymous traffic, and trusted automation. Decide how routes share or separate budgets and whether requests consume one unit or a documented cost. An IP address may combine unrelated callers or change during a session, while a user identifier can let one account distribute abuse across addresses. The contract should state those tradeoffs rather than hiding them inside a cache key.`]},
 {heading:'Choose algorithm behavior clients can observe',body:[`Describe the window or bucket algorithm, capacity, refill or reset behavior, burst allowance, and concurrency semantics. Use a deterministic clock to test the request immediately before and after a boundary. Repeat with a burst arriving at the same timestamp and with delayed counter writes. The expected allowed sequence belongs in the fixture, not only a final count.`,`If route costs differ, send one expensive request and the equivalent work split across cheaper-looking aliases. Prove that the chosen accounting matches resource policy. Cost units should be stable enough for client guidance and observable enough for operators to explain a rejection.`]},
 {heading:'Run through every production replica',body:[`Send a controlled sequence across multiple gateway or application replicas. Record which replica handled each request, the shared counter state, allowed results, rejected results, and reset advice. Independent in-memory counters can multiply the advertised budget. Eventual updates can also admit excess requests or reject a client after another replica reports room.`,`Introduce realistic network delay to the counter store and concurrent requests for one identity. The implementation should have an atomic operation or another proven consistency rule for the selected algorithm. Do not infer correctness from a single-process unit test.`]},
 {heading:'Make 429 responses actionable',body:[`Return status 429 for the reviewed throttling case and test the chosen Retry-After representation through the real gateway. Keep body and headers consistent about when another attempt may succeed. Verify that caches and proxies do not transform the response unexpectedly. A client that retries every rejected request immediately can amplify the load the limiter was meant to control.`,`Test a compliant client that waits, a client that retries too early, and a request that succeeds after the advised interval. If additional rate-limit headers are part of the product contract, define their semantics and test them at boundary conditions rather than emitting approximate values from a different counter.`]},
 {heading:'Decide counter-store failure explicitly',body:[diagnostics['api-rate-limit-contract-review'],`Disconnect or delay the shared store and observe the actual service path. Failing open protects availability but removes the abuse control. Failing closed can turn a store outage into an application outage. A local fallback changes the effective budget across replicas. The service and security owners must choose the behavior for each traffic class, and dashboards must identify when that mode is active.`]},
 {heading:'Protect keys and govern exemptions',body:[`Store only the identifier needed for counting and protect it according to privacy rules. Hashing may reduce casual exposure but does not solve weak or predictable identifiers by itself. Set retention to the operational window and prevent rate-limit diagnostics from becoming a long-lived record of user activity.`,`Health checks, internal jobs, support tools, and partners sometimes need separate budgets. Give each exemption a bounded credential, scope, owner, reason, and expiry. Test an expired exemption and a credential presented to the wrong route. A bypass list with no review date becomes an undocumented second policy.`]},
 {heading:'Observe policy errors separately from demand',body:[`Chart allowed requests, 429 responses, unique counted identities, counter divergence, store latency and faults, retry success, exemption use, and support cases. Separate expected customer demand from suspected abuse and policy misconfiguration. A sudden rise in 429 responses after a routing change may reflect duplicate counting rather than hostile traffic.`,`Keep fixture identifiers and timestamps so operators can trace one decision without logging secrets or full request bodies. Define an alert for replicas disagreeing on remaining budget and another for store failure mode. Those conditions need different owners and recovery actions.`]},
 {heading:'Acceptance covers distributed behavior',body:[acceptance['api-rate-limit-contract-review'],`The API owner receives identity derivation, algorithm definition, cost table, deterministic unit fixtures, multi-replica results, atomicity evidence, 429 and Retry-After contract, client retry tests, store-failure behavior, privacy treatment, exemptions, dashboards, and rollback. Security approves abuse boundaries and failure tradeoffs. The developer implements and measures the control without granting permanent bypasses or changing the public retry contract to make a test pass.`]},
];

const literalSections:Record<string,{heading:string;body:string[]}[]>={
 'postgres-row-level-security-review-offshore-developer':rowSecuritySections,
 'webauthn-passkey-recovery-handoff':passkeySections,
 'node-graceful-shutdown-review':shutdownSections,
 'kubernetes-readiness-gate-review':readinessGateSections,
 'postgres-concurrent-index-handoff':concurrentIndexSections,
 'github-actions-oidc-cloud-boundary':oidcBoundarySections,
 's3-multipart-upload-cleanup-review':multipartCleanupSections,
 'graphql-query-cost-control-review':graphqlCostSections,
 'react-error-boundary-recovery-handoff':reactRecoverySections,
 'container-image-signature-verification-review':imageSignatureSections,
 'dns-cutover-evidence-handoff':dnsCutoverSections,
 'api-rate-limit-contract-review':rateLimitSections,
};

export const october02BlogBatch=topics.map((topic,index)=>{
  const post=makeDailyBlogPost(topic,index,'2026-10-02');
  return {...post,sections:literalSections[topic.slug]};
});
